import { useCallback, useState } from 'react';
import { JxTagInput, JxButton } from '@jinx-ui/react';

export interface ArticleTagsFieldProps {
  defaultValue?: string[];
  onChange?: (tags: string[]) => void;
  label?: string;
  placeholder?: string;
}

function normalize(tags: string[]): string[] {
  const seen = new Set<string>();
  const result: string[] = [];
  for (const raw of tags) {
    const tag = raw.trim();
    const key = tag.toLowerCase();
    if (!tag || seen.has(key)) continue;
    seen.add(key);
    result.push(tag);
  }
  return result;
}

export default function ArticleTagsField({
  defaultValue = [],
  onChange,
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
}: ArticleTagsFieldProps) {
  const [tags, setTags] = useState<string[]>(() => normalize(defaultValue));

  const commit = useCallback(
    (next: string[]) => {
      const cleaned = normalize(next);
      setTags(cleaned);
      onChange?.(cleaned);
    },
    [onChange],
  );

  const removeTag = useCallback(
    (tag: string) => {
      commit(tags.filter((item) => item !== tag));
    },
    [commit, tags],
  );

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-space-2, 0.5rem)',
      }}
    >
      <JxTagInput
        label={label}
        placeholder={placeholder}
        value={tags}
        onValueChange={commit}
      />

      {tags.length > 0 && (
        <ul
          aria-label="Выбранные теги"
          style={{
            display: 'flex',
            flexWrap: 'wrap',
            gap: 'var(--jx-space-2, 0.5rem)',
            margin: 0,
            padding: 0,
            listStyle: 'none',
          }}
        >
          {tags.map((tag) => (
            <li key={tag}>
              <JxButton
                type="button"
                size="sm"
                aria-label={`Удалить тег ${tag}`}
                onClick={() => removeTag(tag)}
              >
                <span>{tag}</span>
                <span aria-hidden="true">✕</span>
              </JxButton>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

